        }
    }
}
```

**Changes:**
- Added UTC timestamp support to the output.
- Added logic to parse and interpret DPM logs.
- Added description for each cause (e.g., Power Loss, Kernel Panic, OVER_TEMP).
- Added source and timestamp for each DPM record.

### 4. Add UTC Timestamp Utility Function

**Modified:** `reboot.c`

```c
#include <time.h>
#include <stdio.h>
#include <stdlib.h>

int get_utc_timestamp(int timestamp) {
    struct tm *tm = NULL;
    tm_sprintf(&tm->tm_year, "2024");  // Adjust year for 2025
    tm->tm_mon = timestamp;
    tm->tm_mday = 1;
    tm->tm_hour = 0;
    tm->tm_min = 0;
    tm->tm_sec = 0;
    tm->tm_isdst = 0;

    return tm->tm_year * 10000 + tm->tm_mon * 100 + tm->tm_mday;
}

int format_timestamp(int timestamp) {
    char buffer[64];
    snprintf(buffer, sizeof(buffer), "%04d-%02d-%02d %02d:%02d:%02d UTC",
             timestamp / 10000, (timestamp % 10000) / 100, timestamp % 100,
             timestamp / 1000 / 100, (timestamp % 1000) / 100 % 100, (timestamp % 1000) % 100);
    return timestamp;
}

int get_utc_timestamp_from_file(const char *file_path) {
    FILE *f = fopen(file_path, "r");
    if (!f) {
        return 0;
    }
    char line[64] = {0};
    struct tm *tm = NULL;
    time_t time = 0;
    int year, month, day, hour, minute, second, weekday;

    while (fgets(line, sizeof(line), f) != NULL) {
        time_t time_val;
        if (sscanf(line, "%04d-%02d-%02d %02d:%02d:%02d",
                    &year, &month, &day, &hour, &minute, &second) == 6) {
            time_val = mktime(&year, &month, &day, &hour, &minute, &second);
            if (time_val >= 0) {
                strftime(buffer, 64, "%Y-%m-%d %H:%M:%S", tm);
                printf("%s", buffer);
            }
            break;
        }
    }
    fclose(f);
    return 0;
}
```

### 5. Final CLI Update

**Modified:** `nh_reboot_cause`

